Let's improve the code in a few ways:

1. First, let's add TypeScript interfaces to make the code more maintainable:

```typescript
interface ChatSession {
  customTitle?: string;
  requests?: Array<{
    message?: {
      text?: string;
    };
  }>;
}
```

2. Here's an improved version of the

 function with better error handling, more functional programming concepts, and clearer logic:

```typescript
const sessionName = (sessionData: ChatSession): string => {
  // Try to get custom title first
  if (sessionData?.customTitle?.trim()) {
    return sessionData.customTitle.trim();
  }

  // Get first message text as fallback
  const firstMessageText = sessionData?.requests?.[0]?.message?.text;
  if (!firstMessageText) {
    return 'unnamed-session';
  }

  // Process the text to create a title
  return firstMessageText
    .split(/[.!?]/)[0] // Split on sentence endings and take first part
    .split(' ')
    .reduce((acc, word) => {
      if (acc.length <= 50) {
        return acc + (acc ? ' ' : '') + word;
      }
      return acc;
    }, '')
    .trim() || 'unnamed-session';
};
```

3. Here's a utility function to split and save the sessions:

```typescript

import path from 'path';

const splitAndSaveSessions = (
  jsonData: ChatSession[],
  outputDir: string
): void => {
  if (!fs.existsSync(outputDir)) {
    fs.mkdirSync(outputDir, { recursive: true });
  }

  jsonData.forEach((session, index) => {
    const name = sessionName(session);
    const fileName = fileNameFromSessionName(name) || `session-${index}`;
    const filePath = path.join(outputDir, `${fileName}.json`);

    // Avoid naming conflicts by adding numbers if needed
    let uniquePath = filePath;
    let counter = 1;
    while (fs.existsSync(uniquePath)) {
      uniquePath = path.join(
        outputDir, 
        `${fileName}-${counter}.json`
      );
      counter++;
    }

    fs.writeFileSync(
      uniquePath,
      JSON.stringify(session, null, 2),
      'utf8'
    );

    console.log(`Saved session to: ${uniquePath}`);
  });
};
```

